SELECT s.s_name,s.s_address FROM tpch_supplier s JOIN tpch_nation n ON s.s_nationkey=n.n_nationkey WHERE s.s_suppkey IN (SELECT ps.ps_suppkey FROM tpch_partsupp ps WHERE ps.ps_partkey IN (SELECT p.p_partkey FROM tpch_part p WHERE p.p_name LIKE 'Part 1%') AND ps.ps_availqty > (SELECT 0.5*COALESCE(SUM(l.l_quantity),0) FROM tpch_lineitem l WHERE l.l_partkey=ps.ps_partkey AND l.l_suppkey=ps.ps_suppkey AND l.l_shipdate>=DATE '1994-01-01' AND l.l_shipdate<DATE '1995-01-01')) AND n.n_name='CANADA' ORDER BY s.s_name;
